class Solution {
public:
    int oddCells(int m, int n, vector<vector<int>>& indices) {
        vector<int> rowInc(m, 0), colInc(n, 0);
        for (auto& idx : indices) {
            rowInc[idx[0]]++;
            colInc[idx[1]]++;
        }
        int oddRows = 0, oddCols = 0;
        for (int i = 0; i < m; i++) {
            if (rowInc[i] % 2 == 1) oddRows++;
        }
        for (int j = 0; j < n; j++) {
            if (colInc[j] % 2 == 1) oddCols++;
        }
        return oddRows * (n - oddCols) + (m - oddRows) * oddCols;
    }
};
